  1→use std::fs;
  2→use std::path::Path;
  3→
  4→use crate::error::CoreError;
  5→
  6→const HOOKS: &[&str] = &["prepare-commit-msg", "post-commit"];
  7→
  8→/// Install engram git hooks into the repository's hooks directory.
  9→///
 10→/// For each hook, if an existing hook script is present, it is renamed
 11→/// to `<hook>.pre-engram` and the new hook chains to it.
 12→pub fn install_hooks(git_dir: &Path) -> Result<(), CoreError> {
 13→    let hooks_dir = git_dir.join("hooks");
 14→    fs::create_dir_all(&hooks_dir)?;
 15→
 16→    for hook_name in HOOKS {
 17→        let hook_path = hooks_dir.join(hook_name);
 18→        let backup_path = hooks_dir.join(format!("{hook_name}.pre-engram"));
 19→
 20→        // If there's an existing hook (and it's not ours), back it up
 21→        if hook_path.exists() {
 22→            let content = fs::read_to_string(&hook_path)?;
 23→            if !content.contains("engram hook-handler") {
 24→                fs::rename(&hook_path, &backup_path)?;
 25→            }
 26→        }
 27→
 28→        let script = generate_hook_script(hook_name, backup_path.exists());
 29→        fs::write(&hook_path, script)?;
 30→        #[cfg(unix)]
 31→        {
 32→            use std::os::unix::fs::PermissionsExt;
 33→            fs::set_permissions(&hook_path, fs::Permissions::from_mode(0o755))?;
 34→        }
 35→    }
 36→
 37→    Ok(())
 38→}
 39→
 40→/// Uninstall engram hooks, restoring originals if they were backed up.
 41→pub fn uninstall_hooks(git_dir: &Path) -> Result<(), CoreError> {
 42→    let hooks_dir = git_dir.join("hooks");
 43→
 44→    for hook_name in HOOKS {
 45→        let hook_path = hooks_dir.join(hook_name);
 46→        let backup_path = hooks_dir.join(format!("{hook_name}.pre-engram"));
 47→
 48→        if hook_path.exists() {
 49→            let content = fs::read_to_string(&hook_path).unwrap_or_default();
 50→            if content.contains("engram hook-handler") {
 51→                fs::remove_file(&hook_path)?;
 52→            }
 53→        }
 54→
 55→        if backup_path.exists() {
 56→            fs::rename(&backup_path, &hook_path)?;
 57→        }
 58→    }
 59→
 60→    Ok(())
 61→}
 62→
 63→fn generate_hook_script(hook_name: &str, has_backup: bool) -> String {
 64→    let mut script = String::from("#!/bin/sh\n");
 65→    script.push_str("# Engram git hook — auto-generated, do not edit\n\n");
 66→
 67→    // Chain to existing hook if backed up
 68→    if has_backup {
 69→        script.push_str(&format!(
 70→            "# Run original hook\n\
 71→             if [ -x \"$(dirname \"$0\")/{hook_name}.pre-engram\" ]; then\n\
 72→             \t\"$(dirname \"$0\")/{hook_name}.pre-engram\" \"$@\"\n\
 73→             \tHOOK_EXIT=$?\n\
 74→             \tif [ $HOOK_EXIT -ne 0 ]; then\n\
 75→             \t\texit $HOOK_EXIT\n\
 76→             \tfi\n\
 77→             fi\n\n"
 78→        ));
 79→    }
 80→
 81→    // Run engram hook handler (fail silently — hooks should not break git)
 82→    script.push_str(&format!(
 83→        "# Run engram hook handler\n\
 84→         if command -v engram >/dev/null 2>&1; then\n\
 85→         \tengram hook-handler {hook_name} \"$@\" || true\n\
 86→         fi\n"
 87→    ));
 88→
 89→    script
 90→}
 91→
