100→        let git_dir = tmp.path();
101→        fs::create_dir_all(git_dir.join("hooks")).unwrap();
102→
103→        install_hooks(git_dir).unwrap();
104→
105→        for hook_name in HOOKS {
106→            let hook_path = git_dir.join("hooks").join(hook_name);
107→            assert!(hook_path.exists(), "Hook {hook_name} should exist");
