105→    #[test]
106→    fn test_session_save_load_cleanup() {
107→        let tmp = TempDir::new().unwrap();
108→        let git_dir = tmp.path();
109→
110→        let session = ActiveSession::new(
111→            EngramId::new(),
112→            AgentInfo {
113→                name: "test-agent".into(),
114→                model: Some("gpt-4".into()),
115→                version: None,
116→            },
117→        );
118→
119→        // Save
120→        session.save(git_dir).unwrap();
121→
122→        // Load
123→        let loaded = ActiveSession::load(git_dir).unwrap();
124→        assert_eq!(loaded.engram_id, session.engram_id);
125→        assert_eq!(loaded.agent.name, "test-agent");
126→        assert!(loaded.commits.is_empty());
127→
128→        // Add commit
129→        let mut loaded = loaded;
130→        loaded.add_commit("abc123", git_dir).unwrap();
131→        let reloaded = ActiveSession::load(git_dir).unwrap();
132→        assert_eq!(reloaded.commits, vec!["abc123"]);
133→
134→        // Cleanup
135→        ActiveSession::cleanup(git_dir);
136→        assert!(ActiveSession::load(git_dir).is_none());
137→    }
