34→/// Auto-detect importable session sources for the given repo root.
35→pub fn detect_sources(repo_root: &Path) -> Result<Vec<ImportSource>, CaptureError> {
36→    let mut sources = Vec::new();
37→
38→    // Check for Claude Code sessions
39→    if let Ok(sessions) = ClaudeCodeImporter::discover_sessions(repo_root) {
40→        for path in sessions {
41→            sources.push(ImportSource::ClaudeCode { session_path: path });
42→        }
43→    }
44→
45→    // Check for Aider history
46→    if let Ok(histories) = AiderImporter::discover(repo_root) {
47→        for path in histories {
48→            sources.push(ImportSource::Aider { history_path: path });
49→        }
50→    }
51→
52→    Ok(sources)
53→}
